import XCTest
@testable import HAOSRunner

final class GrubEnvironmentTests: XCTestCase {
    private func sampleBlock(aTry: Int) -> Data {
        let content = """
        # GRUB Environment Block
        # WARNING: Do not edit this file by tools other than grub-editenv!!!
        ORDER=A B
        A_OK=1
        A_TRY=\(aTry)
        B_TRY=0
        B_OK=0
        MACHINE_ID=45acb10930844d2ebc6fd04d1d79c5b2

        """
        return Data((content + String(repeating: "#", count: 1024 - content.count)).utf8)
    }

    func testResetsTryCountersAndPreservesEverythingElse() throws {
        let repaired = try XCTUnwrap(GrubEnvironment.resettingTryCounters(sampleBlock(aTry: 3)))
        XCTAssertEqual(repaired.count, 1024)
        let text = try XCTUnwrap(String(data: repaired, encoding: .ascii))
        XCTAssertTrue(text.contains("A_TRY=0\n"))
        XCTAssertTrue(text.contains("B_TRY=0\n"))
        XCTAssertTrue(text.contains("A_OK=1\n"))
        XCTAssertTrue(text.contains("ORDER=A B\n"))
        XCTAssertTrue(text.contains("MACHINE_ID=45acb10930844d2ebc6fd04d1d79c5b2\n"))
    }

    func testRejectsWrongSizeBlock() {
        XCTAssertNil(GrubEnvironment.resettingTryCounters(Data("A_TRY=3\n".utf8)))
    }

    func testRejectsBlockWithoutVariables() {
        let padding = Data(String(repeating: "#", count: 1024).utf8)
        XCTAssertNil(GrubEnvironment.resettingTryCounters(padding))
    }
}
